<?php namespace App\Jobs; use App\Models\EventAnnouncement; use App\Models\Ticket; use App\Contracts\SmsProvider; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Mail; use Throwable; class SendAnnouncementJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=4; public array $backoff=[30,120,600]; public int $timeout=120; public function __construct(public int $announcementId){} public function handle(SmsProvider $sms):void{$a=EventAnnouncement::findOrFail($this->announcementId);$a->update(['status'=>'sending']);Ticket::whereHas('booking',fn($q)=>$q->where('event_id',$a->event_id)->where('status','paid'))->with('booking.user')->orderBy('id')->chunkById(400,function($tickets)use($a,$sms){foreach($tickets as $t){$user=$t->booking->user;$key="announce-{$a->id}-ticket-{$t->id}";if($user->email&&cache()->add("sent:$key",true,86400*30))Mail::raw($a->message,fn($m)=>$m->to($user->email)->subject('إعلان منظم الفعالية'));}});$a->update(['status'=>'sent']);}public function failed(?Throwable $e):void{EventAnnouncement::whereKey($this->announcementId)->update(['status'=>'failed']);logger()->error('Announcement failed',['id'=>$this->announcementId,'error'=>$e?->getMessage()]);}}
